export default function plan({ body }) {
  const m = body?.message;
  if (!m || !Number.isSafeInteger(m?.chat?.id))
    return {
      hasInput: false,
      voice: false,
      chatId: "0",
      text: "",
      fileId: "-",
      fileRequest: { file_id: "-" },
    };
  const hasVoice = typeof m.voice?.file_id === "string" && !!m.voice.file_id,
    text = typeof m.text === "string" ? m.text.trim() : "";
  return {
    hasInput: hasVoice || !!text,
    voice: hasVoice,
    chatId: String(m.chat.id),
    text,
    fileId: hasVoice ? m.voice.file_id : "-",
    fileRequest: { file_id: hasVoice ? m.voice.file_id : "-" },
  };
}

