import { Buffer } from "node:buffer";
export default async function audio({ botToken, verified, reply, statusCode, fileId }, context) {
  if (verified !== true || typeof botToken !== "string" || !/^\d+:[A-Za-z0-9_-]+$/.test(botToken))
    throw Error("Verify the Telegram bot token");
  const f = reply?.result,
    path = f?.file_path;
  if (
    statusCode !== 200 ||
    reply?.ok !== true ||
    f?.file_id !== fileId ||
    typeof path !== "string" ||
    !path ||
    path.startsWith("/") ||
    path.split("/").some((x) => !x || x === "." || x === "..") ||
    /[?#\\\x00-\x20]/.test(path)
  )
    throw Error("Telegram did not confirm a valid voice file");
  try {
    const r = await context.fetch(
      "https://api.telegram.org/file/bot" +
        botToken +
        "/" +
        path.split("/").map(encodeURIComponent).join("/"),
      { method: "GET" },
    );
    if (!r.ok) throw Error("download");
    const bytes = Buffer.from(await r.arrayBuffer());
    if (!bytes.length || (typeof f.file_size === "number" && f.file_size !== bytes.length))
      throw Error("size");
    return {
      file: { name: "voice.ogg", mimetype: "audio/ogg", content_base64: bytes.toString("base64") },
    };
  } catch {
    throw Error("Telegram voice download failed");
  }
}

