export default function next({ result, previous, projectId }) {
  if (typeof projectId !== "string" || !projectId.trim() || projectId.startsWith("YOUR_"))
    throw Error("Configure Todoist project ID");
  if (!Array.isArray(result?.tasks) || !result.tasks.length) throw Error("No tasks returned");
  for (const t of result.tasks)
    if (
      typeof t?.content !== "string" ||
      !t.content.trim() ||
      !Number.isInteger(t.priority) ||
      t.priority < 1 ||
      t.priority > 4
    )
      throw Error("Invalid generated task");
  const index = previous == null ? 0 : previous.index + 1;
  if (!Number.isInteger(index) || index < 0 || index > result.tasks.length)
    throw Error("Invalid task progress");
  return {
    state: { index },
    more: index < result.tasks.length,
    task: result.tasks[index] ?? { content: "-", priority: 1 },
    projectId,
  };
}

