export default async function create({ task, projectId }, context) {
  const r = await context.actions.call("todoist.create_task", {
    content: task.content,
    priority: task.priority,
    projectId,
  });
  const t = r?.task;
  if (
    !t ||
    typeof t.id !== "string" ||
    !t.id ||
    typeof t.content !== "string" ||
    !t.content ||
    typeof t.url !== "string" ||
    !t.url
  )
    throw Error("Todoist did not confirm task; inspect before retry");
  const text = `Task : ${t.content} Task Link :${t.url}`;
  if (text.length > 4096) throw Error("Task created but confirmation is too long");
  return { text };
}
